#!/usr/bin/env bash
# Creates .kamal/secrets (git-ignored) with freshly generated passwords.
# Idempotent: never overwrites an existing file.
#
# Usage: bin/migration/init_secrets.sh
set -euo pipefail
cd "$(dirname "$0")/../.."

SECRETS=.kamal/secrets

if [ -e "$SECRETS" ]; then
  echo "OK: $SECRETS already exists — leaving it untouched."
  exit 0
fi

if ! git check-ignore -q "$SECRETS"; then
  echo "ERROR: $SECRETS is not git-ignored; refusing to create it." >&2
  exit 1
fi

rand() { openssl rand -hex "$1"; }

umask 077
cat > "$SECRETS" <<SECRETS
# Generated by bin/migration/init_secrets.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ).
# NEVER commit this file. Keep a copy in your password manager: losing
# SECRET_KEY_BASE logs everybody out; losing MYSQL_ROOT_PASSWORD locks you
# out of the database.

# GitHub token with write:packages, taken from your environment.
KAMAL_REGISTRY_PASSWORD=\$KAMAL_REGISTRY_PASSWORD

SECRET_KEY_BASE=$(rand 64)

MYSQL_ROOT_PASSWORD=$(rand 24)
REDMINE_DB_PASSWORD=$(rand 24)
MYSQL_PASSWORD=\$REDMINE_DB_PASSWORD

# Fill in if SMTP is configured in config/deploy.yml.
SMTP_PASSWORD=
SECRETS

echo "Created $SECRETS (mode 600)."
echo "Next: export KAMAL_REGISTRY_PASSWORD=<github token with write:packages>"
echo "      (or replace that line with the literal token) and back the file up."
